def _route_hobby(toks, base_lf):
    if any(w in _MUS_W for w in toks): return base_lf
    if any(w in _GAM_W for w in toks): return base_lf + 1
    if any(w in _MOV_W for w in toks): return base_lf + 2
    if any(w in _SPT_W for w in toks): return base_lf + 3
    return base_lf + 4


def load_txt_samples(sample_map, load_fn):
    for fn, lf, cap in (("looking_for_ask.txt", 22, 600), ("name_ask.txt", 27, 400), ("name_tell.txt", 28, 800), ("rel_status_ask.txt", 39, 500)):
        for s in load_fn(fn, cap):
            sample_map[s] = (lf, np.float32(4.0))

    for s in load_fn("looking_for_state.txt", 600):
        toks = [w.strip("'?,") for w in s.split()]
        if "here" in toks and not any(w in ("looking", "lookin", "loking", "finding", "for", "to") for w in toks):
            continue
        if any(w in ("gf", "girlfriend", "girl", "gril", "female", "famle", "woman", "girls") for w in toks): lf = 24
        elif any(w in ("bf", "boyfriend", "boy", "guy", "male", "man") for w in toks): lf = 25
        elif any(w in ("dating", "relationship", "love", "romance", "partner", "soulmate") for w in toks): lf = 26
        else: lf = 23
        sample_map[s] = (lf, np.float32(5.0))

    for s in load_fn("hobbies_ask.txt", 600):
        sample_map[s] = (_route_hobby([w.strip("'?,") for w in s.split()], 29), np.float32(5.0))
    for s in load_fn("hobbies_tell.txt", 600):
        sample_map[s] = (_route_hobby([w.strip("'?,") for w in s.split()], 34), np.float32(5.0))
    for s in load_fn("rel_status_tell.txt", 500):
        toks = [w.strip("'?,") for w in s.split()]
        lf = 40 if any(w in _NEG_W for w in toks) else (42 if any(w in _MAR_W for w in toks) else (40 if any(w in _SNG_W for w in toks) else 41))
        sample_map[s] = (lf, np.float32(5.0))